<?php
/**
 * + Add Complaint. Internal users only (no public portal in this phase).
 *
 * The complaint number is generated by the system when the form is saved.
 * Before/After pictures and attachments chosen here are uploaded in small
 * batches right after the complaint is created (assets/js/complaints.js),
 * so even a 100-picture folder is not limited by PHP's post size.
 */
declare(strict_types=1);

require_once dirname(__DIR__, 2) . '/config.php';
require_once __DIR__ . '/bootstrap.php';

if (!IS_INSTALLED) {
    redirect('install/index.php');
}

Permission::require('complaint.create');

$sources = cmp_lookup_options('complaint_sources');
$types = cmp_lookup_options('complaint_types');
$priorities = cmp_lookup_options('complaint_priorities');
$regions = Database::fetchAll("SELECT id, name FROM regions WHERE status = 'active' ORDER BY name ASC");
$ready = $sources && $types && $priorities && $regions;

$form = [];
foreach (['complainant_name', 'complainant_address', 'phone', 'source_id', 'type_id', 'priority_id', 'description', 'complaint_date',
          'complaint_time', 'region_id', 'district_id', 'tehsil_id', 'uc_id', 'beat_id', 'location_address', 'latitude', 'longitude'] as $k) {
    $form[$k] = old($k);
}
$form['complaint_date'] = $form['complaint_date'] ?: date('Y-m-d');
$form['complaint_time'] = $form['complaint_time'] ?: date('H:i');

$cascade = [
    'district' => cmp_geography_children('district', (int)$form['region_id']),
    'tehsil' => cmp_geography_children('tehsil', (int)$form['district_id']),
    'uc' => cmp_geography_children('uc', (int)$form['tehsil_id']),
    'beat' => cmp_geography_children('beat', (int)$form['uc_id']),
];

$duplicates = $_SESSION['cmp_duplicates'] ?? [];
unset($_SESSION['cmp_duplicates']);
$isEdit = false;

$pageTitle = 'Add complaint';
$layout = 'app';
$extraScripts = ['complaints.js'];

require INCLUDES_PATH . '/header.php';
?>

<a class="btn btn--ghost no-print" href="<?= e(base_url('modules/complaints/index.php')) ?>" style="margin-bottom:16px">
    <?= icon('arrow-left') ?><span class="btn__label">Back to complaints</span>
</a>

<?php require INCLUDES_PATH . '/components/alerts.php'; ?>

<?php if (!$ready): ?>
    <div class="card">
        <div class="empty-state">
            <?= icon('settings') ?>
            <h3 style="margin-bottom:6px">Setup needed before complaints can be created</h3>
            <p style="margin:0 0 12px">
                <?php
                $missing = [];
                if (!$sources) { $missing[] = 'a Complaint Source'; }
                if (!$types) { $missing[] = 'a Complaint Type'; }
                if (!$priorities) { $missing[] = 'a Priority'; }
                if (!$regions) { $missing[] = 'a Region/District/Tehsil/UC (Structure)'; }
                echo e('Add ' . implode(', ', $missing) . ' first.');
                ?>
            </p>
            <?php if (can('complaint.config')): ?>
                <a class="btn btn--primary" href="<?= e(base_url('modules/complaints/config.php')) ?>"><span class="btn__label">Open configuration</span></a>
            <?php else: ?>
                <p class="field__hint">Ask an administrator with the Configuration permission.</p>
            <?php endif; ?>
        </div>
    </div>
<?php else: ?>

<?php if ($duplicates): ?>
    <div class="card cmp-dup-warning" role="alert">
        <h3 class="card__title"><?= icon('alert') ?>A similar complaint already exists.</h3>
        <p class="card__subtitle">Check these before creating another. Nothing has been saved yet.</p>
        <ul class="cmp-dup-list">
            <?php foreach ($duplicates as $d): ?>
                <li><a href="<?= e(base_url('modules/complaints/complaint-view.php?id=' . (int)$d['id'])) ?>" target="_blank" rel="noopener"><strong><?= e((string)$d['complaint_number']) ?></strong></a>
                    — <?= e((string)$d['complainant_name']) ?>, <?= e((string)$d['type_name']) ?>, <?= e((string)$d['uc_name']) ?>, <?= e(cmp_fmt_date((string)$d['complaint_date'])) ?> (<?= e(cmp_status_label((string)$d['status'])) ?>)</li>
            <?php endforeach; ?>
        </ul>
        <p class="field__hint">To create it anyway, tick the box below and press <em>Create complaint</em> again. Otherwise just leave this page.</p>
    </div>
<?php endif; ?>

<form class="card cmp-form" id="complaint-form" method="post" action="<?= e(base_url('modules/complaints/process/complaint-save.php')) ?>" novalidate
      data-ajax-url="<?= e(base_url('modules/complaints/process/complaint-save.php')) ?>"
      data-evidence-url="<?= e(base_url('modules/complaints/process/evidence-upload.php')) ?>"
      data-attachment-url="<?= e(base_url('modules/complaints/process/attachment-upload.php')) ?>"
      data-csrf="<?= e(Security::csrfToken()) ?>">
    <?= csrf_field() ?>
    <?php require __DIR__ . '/partials/complaint-form.php'; ?>

    <?php if (can('complaint.evidence_before') || can('complaint.attach')): ?>
        <fieldset class="cmp-fieldset">
            <legend>Evidence &amp; attachments (optional)</legend>
            <?php if (can('complaint.evidence_before')): ?>
                <div class="field">
                    <span class="field__label">Before pictures</span>
                    <div class="cmp-picker-row">
                        <label class="btn"><?= icon('folder') ?><span class="btn__label">Upload Before Pictures — choose folder</span>
                            <input type="file" hidden webkitdirectory multiple data-queue="before" data-queue-folder></label>
                        <label class="btn btn--ghost"><?= icon('image') ?><span class="btn__label">or choose files</span>
                            <input type="file" hidden multiple accept="image/jpeg,image/png,image/webp" data-queue="before"></label>
                        <span class="field__hint" data-queue-info="before">No pictures chosen.</span>
                    </div>
                    <p class="field__hint">Pictures you choose here are Before evidence — the system never guesses. After pictures are added later, from the complaint page.</p>
                </div>
            <?php endif; ?>
            <?php if (can('complaint.attach')): ?>
                <div class="field">
                    <span class="field__label">Attachments</span>
                    <div class="cmp-picker-row">
                        <label class="btn btn--ghost"><?= icon('paperclip') ?><span class="btn__label">Choose documents</span>
                            <input type="file" hidden multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png" data-queue="attachment"></label>
                        <span class="field__hint" data-queue-info="attachment">No documents chosen.</span>
                    </div>
                    <p class="field__hint">PDF, DOC/DOCX, XLS/XLSX, JPG, PNG — up to <?= e(cmp_fmt_bytes(CMP_ATTACH_MAX_BYTES)) ?> each.</p>
                </div>
            <?php endif; ?>
        </fieldset>
    <?php endif; ?>

    <?php if ($duplicates): ?>
        <label class="cmp-ack"><input type="checkbox" name="ack_duplicate" value="1"> I have reviewed the similar complaint(s) and still want to create this one.</label>
    <?php endif; ?>

    <div class="cmp-progress" data-progress hidden>
        <div class="cmp-progress__bar"><i data-progress-bar></i></div>
        <p class="field__hint" data-progress-text></p>
    </div>

    <div class="toolbar" style="margin:var(--space-4) 0 0">
        <button type="submit" class="btn btn--primary" data-submit><span class="spinner"></span><?= icon('check-big') ?><span class="btn__label">Create complaint</span></button>
        <a class="btn btn--ghost" href="<?= e(base_url('modules/complaints/index.php')) ?>"><span class="btn__label">Cancel</span></a>
    </div>
</form>

<div class="cmp-modal" id="dup-modal" hidden role="dialog" aria-modal="true" aria-labelledby="dup-title">
    <div class="cmp-modal__box">
        <h3 id="dup-title"><?= icon('alert') ?> A similar complaint already exists.</h3>
        <p class="card__subtitle">Review the existing complaint(s) below. You decide whether to continue.</p>
        <ul class="cmp-dup-list" data-dup-list></ul>
        <div class="toolbar" style="margin:var(--space-4) 0 0">
            <button type="button" class="btn btn--primary" data-dup-continue><span class="btn__label">Continue — create anyway</span></button>
            <button type="button" class="btn btn--ghost" data-dup-cancel><span class="btn__label">Go back &amp; edit</span></button>
            <a class="btn btn--ghost" href="<?= e(base_url('modules/complaints/index.php')) ?>"><span class="btn__label">Don't create it</span></a>
        </div>
    </div>
</div>

<?php endif; ?>

<?php clear_old(); require INCLUDES_PATH . '/footer.php'; ?>
